/**
 * Turn a MIME type pattern into a case-insensitive regular expression.
 *
 * Patterns may contain `*` wildcards which match any sequence of characters,
 * so `application/vnd.*+json` matches `application/vnd.api+json`. Every other
 * character is treated literally.
 */
const patternToRegExp = (pattern: string): RegExp => {
  const escaped = pattern.replaceAll(/[.*+?^${}()|[\]\\]/g, (match) => (match === '*' ? '.*' : `\\${match}`))
  return new RegExp(`^${escaped}$`, 'i')
